text:
--hub-account-button-border-color: light-dark(var(--color-gray-30), var(--color-gray-60));
--hub-account-primary-button-color: var(--color-surface-base);
--hub-account-primary-button-background: var(--color-primary-default);
--hub-account-primary-button-background-hover: var(--color-primary-hover);
--hub-account-primary-button-background-active: var(--color-primary-pressed);
--hub-account-primary-button-background-focus: var(--color-primary-hover);
--hub-account-primary-button-border: var(--color-primary-hover);
--hub-account-primary-button-border-active: var(--color-primary-pressed);
--hub-account-secondary-button-color: var(--color-text-base);
--hub-account-secondary-button-background: var(--color-surface-subtle);
/* TODO: Update to use proper defined light-dark varients from colors.css */
--hub-account-secondary-button-background-hover: light-dark(var(--color-surface-subtle), var(--color-surface-base));
--hub-account-secondary-button-background-active: light-dark(var(--color-surface-border), var(--color-surface-lower));
--hub-account-secondary-button-background-focus: light-dark(var(--color-surface-subtle), var(--color-surface-base));
--hub-account-secondary-button-border: var(--color-surface-border);
--hub-account-secondary-button-border-active: var(--color-surface-border-intense);
--hub-account-button-outline-focus: var(--color-primary-hover);
--hub-account-button-hover-active-color: light-dark(var(--color-surface-border), var(--color-surface-lower));
--hub-border-color: light-dark(var(--color-primary-soft), var(--color-primary-default));
--hub-divider-color: var(--color-surface-base);
--hub-loader-background: var(--color-surface-base);
--hub-loader-color: var(--color-primary-default);
--hub-floating-button-line-height: 1.3em;
--hub-width: 500px;
--hub-manual-config-gap: calc(calc(4 * var(--space-step)) + var(--hub-input-error-message-font-size));

--hub-input-height: 33px;
--hub-input-border-radius: 3px;
--hub-input-border-color: color-mix(in srgb, currentColor 50%, transparent);
--hub-input-error-message-font-size: 0.846rem;
--hub-close-button-color: var(--color-text-base);
--hub-close-button-hover-background: var(--color-surface-subtle);
--hub-close-button-active-background: var(--color-text-muted);
--hub-close-button-focus-background: var(--color-surface-subtle);
--hub-close-button-focus-outline-color: var(--color-surface-border-intense);
